const files=["/home/apnex/taceng/context-lab/incoming/agp-browser-scale-public-binding-request.md","docs/reviews/browser-peer-scale-assurance/browser-scale-public-binding.md","docs/BOARD.md","docs/VERIFICATION.md"];
