scope.command:
node --input-type=module -e 'import fs from "node:fs";import cp from "node:child_process";import crypto from "node:crypto";import path from "node:path";import assert from "node:assert/strict";
const receiptPath="docs/reviews/browser-peer-scale-assurance/browser-scale-public-binding-handoff-checks.json";
const receipt=JSON.parse(fs.readFileSync(receiptPath,"utf8"));const before=receipt.baseline.data;
const agp="/home/apnex/taceng/agp",context="/home/apnex/taceng/context-lab";
const sha=b=>crypto.createHash("sha256").update(b).digest("hex");
const git=(cwd,...args)=>cp.execFileSync("git",args,{cwd,encoding:"utf8"});
const identity=p=>{const b=fs.readFileSync(p);return{path:p,bytes:b.length,sha256:sha(b)}};
const replaceOnce=(text,from,to)=>{assert.equal(text.split(from).length,2,"replacement must be unique: "+from);return text.replace(from,to)};
const source=fs.readFileSync(receipt.delivery.sourcePath,"utf8");const delivered=fs.readFileSync(receipt.delivery.targetPath,"utf8");
assert.equal(sha(source),before[agp].files[before.sourcePath].sha256);
let projected=source;
for(const change of receipt.delivery.linkChanges){
 assert.ok(projected.includes(change.old));
 const [oldPath,oldAnchor]=change.old.slice(2,-1).split("#");const [newPath,newAnchor]=change.next.slice(2,-1).split("#");
 assert.equal(path.resolve(path.dirname(receipt.delivery.sourcePath),oldPath),path.resolve(path.dirname(receipt.delivery.targetPath),newPath));assert.equal(oldAnchor,newAnchor);
 projected=projected.split(change.old).join(change.next);
}
for(const change of receipt.delivery.administrativeChanges)projected=replaceOnce(projected,change.old,change.next);
assert.equal(delivered,projected,"placed copy must equal complete source plus declared transforms");
let reversed=delivered;
for(const change of [...receipt.delivery.administrativeChanges].reverse())reversed=replaceOnce(reversed,change.next,change.old);
for(const change of [...receipt.delivery.linkChanges].reverse())reversed=reversed.split(change.next).join(change.old);
assert.equal(reversed,source,"inverse transforms must recover complete source bytes");
const substantive=text=>text.slice(text.indexOf("## 1. "),text.indexOf("## 6. "));
let deliveredSections=substantive(delivered);
for(const change of receipt.delivery.linkChanges)deliveredSections=deliveredSections.split(change.next).join(change.old);
assert.equal(deliveredSections,substantive(source),"all five substantive sections must remain exact except resolved links");
let board=fs.readFileSync(agp+"/docs/BOARD.md","utf8");
for(const change of receipt.tracking.boardChanges)board=replaceOnce(board,change.next,change.old);
assert.equal(sha(board),before[agp].files["docs/BOARD.md"].sha256,"only four current board entries may change");
let verification=fs.readFileSync(agp+"/docs/VERIFICATION.md","utf8");
verification=replaceOnce(verification,receipt.tracking.section,"");
verification=replaceOnce(verification,receipt.tracking.mx22.next,receipt.tracking.mx22.old);
assert.equal(sha(verification),before[agp].files["docs/VERIFICATION.md"].sha256,"historical verification must be preserved");
const repositories={};
for(const cwd of [agp,context]){
 const prior=before[cwd];
 assert.equal(git(cwd,"rev-parse","HEAD").trim(),prior.head);
 assert.equal(git(cwd,"rev-parse","origin/main").trim(),prior.origin);
 assert.equal(git(cwd,"diff","--cached","--binary"),prior.index);
 const newPath=cwd===agp?receiptPath:path.relative(context,receipt.delivery.targetPath);
 const dirty=git(cwd,"ls-files","--modified","--others","--exclude-standard","-z").split("\0").filter(Boolean).sort();
 assert.deepEqual(dirty,[...prior.dirty,newPath].sort(),"no unexpected dirty paths");
 const permitted=cwd===agp?new Set(["docs/BOARD.md","docs/VERIFICATION.md"]):new Set();
 let unchanged=0;
 for(const [p,expected] of Object.entries(prior.files)){
  if(permitted.has(p))continue;
  const actual=identity(path.join(cwd,p));assert.equal(actual.sha256,expected.sha256,p+" hash changed");assert.equal(actual.bytes,expected.bytes,p+" byte count changed");unchanged++;
 }
 repositories[cwd]={head:prior.head,origin:prior.origin,indexUnchanged:true,priorDirtyPaths:prior.dirty.length,currentDirtyPaths:dirty.length,newPaths:[newPath],preExistingFilesCompared:Object.keys(prior.files).length,unchangedFiles:unchanged,allowedTrackingChanges:[...permitted],otherDirtyFilesPreserved:prior.dirty.length-permitted.size};
}
const packet=before[agp].tracked.filter(p=>p.startsWith("docs/reviews/browser-peer-scale-assurance/"));assert.equal(packet.length,20);
for(const p of packet)assert.deepEqual(fs.readFileSync(path.join(agp,p)),cp.execFileSync("git",["show",before[agp].head+":"+p],{cwd:agp}),p+" differs from frozen commit");
const kit="/home/apnex/taceng/mission-kit";assert.equal(git(kit,"rev-parse","HEAD").trim(),before.missionKit.head);assert.equal(git(kit,"status","--porcelain=v1"),before.missionKit.status);
for(const p of [receipt.delivery.targetPath,receiptPath]){const text=fs.readFileSync(p,"utf8");assert.equal(/[\t ]+$/mu.test(text),false,p+" has trailing whitespace");assert.ok(text.endsWith("\n"),p+" missing final newline");}
console.log(JSON.stringify({result:"PASS",measuredAt:new Date().toISOString(),environment:{node:process.version,platform:process.platform,arch:process.arch},source:identity(receipt.delivery.sourcePath),placed:identity(receipt.delivery.targetPath),tracking:{board:identity(agp+"/docs/BOARD.md"),verification:identity(agp+"/docs/VERIFICATION.md"),changedBoardEntries:receipt.tracking.boardChanges.length,verificationChange:"Current MX22 plus appended section 4.78 only; all historical text preserved"},fidelity:{completeRoundTrip:true,substantiveSectionsUnchanged:true,linkDestinationsPreserved:receipt.delivery.linkChanges.length,administrativeChanges:receipt.delivery.administrativeChanges.length},repositories,frozenPacket:{files:packet.length,revision:before[agp].head,workingBytesEqualCommittedBytes:true},missionKit:before.missionKit,receiptSelfHash:"Excluded to avoid a self-referential digest"},null,2));'

